import pathlib,tarfile,sys,time,json,io,re,os
p=pathlib.Path(sys.argv[1]);q=pathlib.Path(sys.argv[2])
def temporary(name):
 return bool(re.fullmatch(r"\..+\.json\.[A-Za-z0-9_-]+",name) or re.fullmatch(r".+\.tmp-\d+(?:-\d+)?",name))
def add(t,path,name):
 if temporary(path.name):return
 if path.is_dir():
  t.add(path,arcname=name,recursive=False)
  for child in sorted(path.iterdir()):add(t,child,name+'/'+child.name)
 else:t.add(path,arcname=name,recursive=False)
