 for n in ['STATE.json','PREDECESSOR-TERMINAL.json','HOST-INVOKE-INTENT.json','HOST-RETURN.json']:
  if (q/n).exists():add(t,q/n,'QUEUE-'+n)
 if (q/'queue.json').exists():
  pred=pathlib.Path(json.loads((q/'queue.json').read_bytes())['predecessor_root'])/'GENERATION_COMPLETE.json'
  if pred.exists():add(t,pred,'RESOURCE-PREDECESSOR-GENERATION-COMPLETE.json')
